
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>doutor OFICINA — A voz do motorista brasileiro</title>

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
<link rel="stylesheet" href="assets/css/style.css">
<!-- Quill.js CSS -->
<link href="https://cdn.quilljs.com/1.3.6/quill.snow.css" rel="stylesheet">

</head>
<body>

<!-- ══ HEADER ══ -->
<header>
  <nav class="nav">
    <a class="logo" href="#" onclick="showPage('home')">
      <img src="data:image/png;base64," alt="Doutor Oficina" style="height:110px;width:auto;">

    </a>

    <div class="nav-actions">
      <a class="nav-link" href="#" onclick="showPage('home')">Ranking</a>
      <a class="nav-link" href="#" onclick="showPage('compare')">Comparar</a>
      <div id="nav-auth-area">
        <a class="nav-link" href="#" onclick="openAuth('login')">Entrar</a>
        <button class="btn-nav-reclamar" onclick="requireAuth()">+ Reclamar</button>
      </div>
    </div>
  </nav>
</header>

<!-- ══ BARRA DE BUSCA AVANÇADA ══ -->
<div class="search-bar-wrap">
  <div class="search-bar-inner">
    <div class="search-tabs">
      <button class="stab active" onclick="switchSearchTab(this,'text')">🔍 Busca livre</button>
      <button class="stab" onclick="switchSearchTab(this,'fipe')">🚗 Escolha seu veículo</button>
    </div>

    <!-- Tab: texto livre -->
    <div class="search-panel active" id="stab-text">
      <div class="search-free">
        <input type="text" id="search-free-input"
          placeholder="Digite marca, modelo, problema…"
          oninput="renderSuggestions(this.value)"
          onkeydown="if(event.key==='Enter')doFreeSearch()" />
        <button class="sb-btn" onclick="doFreeSearch()">Buscar</button>
      </div>
      <div class="search-suggestions" id="search-suggestions"></div>
    </div>

    <!-- Tab: FIPE -->
    <div class="search-panel" id="stab-fipe">
      <div class="search-fipe-row">
        <div class="sfipe-group">
          <label class="sfipe-label">Tipo</label>
          <select class="sfipe-select" id="sb-type" onchange="sbLoadBrands()">
            <option value="carros">🚗 Carros</option>
            <option value="motos">🏍️ Motos</option>
            <option value="caminhoes">🚚 Caminhões</option>
          </select>
        </div>
        <div class="sfipe-group">
          <label class="sfipe-label">Marca</label>
          <select class="sfipe-select" id="sb-brand" onchange="sbLoadModels()" disabled>
            <option>Carregando…</option>
          </select>
        </div>
        <div class="sfipe-group">
          <label class="sfipe-label">Modelo</label>
          <select class="sfipe-select" id="sb-model" onchange="sbLoadYears()" disabled>
            <option>Selecione a marca</option>
          </select>
        </div>
        <div class="sfipe-group">
          <label class="sfipe-label">Ano</label>
          <select class="sfipe-select" id="sb-year" onchange="sbShowPrice()" disabled>
            <option>Selecione o modelo</option>
          </select>
        </div>
        <button class="sb-btn" onclick="doFipeSearch()">Buscar</button>
      </div>
      <div class="sb-fipe-result" id="sb-fipe-result"></div>
    </div>
  </div>
</div>

<!-- ══ PAGE HOME ══ -->
<div id="page-home">

  <section class="hero">
    <div class="hero-circles"><span></span><span></span></div>
    <div class="hero-content">
      <h1>
        Seu veículo te<br>
        <span class="accent">decepcionou?</span><br>
        <span class="dim">A gente precisa saber.</span>
      </h1>
      <p>Registre problemas com seu carro, moto ou caminhão para obter soluções e ajudar milhares de brasileiros a fazer uma compra mais segura.</p>
      <div class="hero-ctas">
        <button class="btn-primary" onclick="requireAuth()">🚨 Fazer reclamação</button>
        <button class="btn-outline" onclick="document.getElementById('ranking-section').scrollIntoView({behavior:'smooth'})">📊 Ver ranking de confiabilidade</button>
      </div>
      <div class="hero-badge-wrap">
        <div class="hero-badge"><span class="live-dot"></span>12.483 reclamações registradas</div>
      </div>
    </div>
  </section>

  <div class="stats">
    <div class="stats-inner">
      <div class="stat"><div class="stat-n">12.483</div><div class="stat-l">Reclamações</div></div>
      <div class="stat-div"></div>
      <div class="stat"><div class="stat-n">847</div><div class="stat-l">Modelos avaliados</div></div>
      <div class="stat-div"></div>
      <div class="stat"><div class="stat-n">68%</div><div class="stat-l">Resolvidas</div></div>
      <div class="stat-div"></div>
      <div class="stat"><div class="stat-n">94</div><div class="stat-l">Marcas cadastradas</div></div>
    </div>
  </div>

  <!-- VEÍCULOS EM DESTAQUE -->
  <section class="section section-alt">
    <div class="section-inner">
      <div class="section-header">
        <h2 class="section-title">Veículos mais <span class="accent">avaliados</span></h2>
        <a href="#" class="see-all" onclick="checkLoginAndShowAllVehicles()">Ver todos →</a>
      </div>
      <div class="vehicles-grid" id="vehicles-grid"></div>
    </div>
  </section>

  <!-- SEÇÃO PARALLAX -->
  <div class="parallax-section" style="background-image: url('assets/car_engine_problem.png')">
    <div class="parallax-content">
    </div>
  </div>

  <!-- RECLAMAÇÕES RECENTES -->
  <section class="section">
    <div class="section-inner">
      <div class="section-header">
        <h2 class="section-title">Reclamações <span class="accent">recentes</span></h2>
        <a href="#" class="see-all">Ver todas →</a>
      </div>
      <!-- FILTROS -->
      <div class="filters-bar">
        <span class="filter-label">Filtrar:</span>
        <select class="filter-select" id="filter-status" onchange="applyFilters()">
          <option value="">Todos os status</option>
          <option value="s-open">Abertos</option>
          <option value="s-progress">Em análise</option>
          <option value="s-resolved">Resolvidos</option>
        </select>
        <select class="filter-select" id="filter-brand" onchange="applyFilters()">
          <option value="">Todas as marcas</option>
          <option>Hyundai</option><option>Chevrolet</option><option>Jeep</option>
          <option>Honda</option><option>Toyota</option><option>Volkswagen</option>
          <option>Fiat</option><option>Yamaha</option>
          <option>Mercedes-Benz</option><option>Scania</option><option>Volvo</option><option>DAF</option>
        </select>
        <select class="filter-select" id="filter-state" onchange="applyFilters()">
          <option value="">Todos os estados</option>
          <option>SP</option><option>RJ</option><option>MG</option><option>RS</option>
          <option>PR</option><option>SC</option><option>BA</option><option>GO</option>
        </select>
        <button class="filter-clear" onclick="clearFilters()">✕ Limpar filtros</button>
      </div>
      <div class="complaints-list" id="complaints-list"></div>
    </div>
  </section>

  <!-- RANKING -->
  <section class="section section-alt" id="ranking-section">
    <div class="section-inner">
      <div class="section-header">
        <h2 class="section-title">🏆 Ranking de <span class="accent">confiabilidade</span></h2>
        <a href="#" class="see-all">Ranking completo →</a>
      </div>
      <div class="ranking-grid" id="ranking-grid"></div>
    </div>
  </section>

  <!-- COMO FUNCIONA -->
  <section class="section">
    <div class="section-inner">
      <div class="section-header">
        <h2 class="section-title">Como <span class="accent">funciona</span></h2>
      </div>
      <div class="how-grid">
        <div class="how-card">
          <div class="how-num">1</div>
          <div class="how-icon">🚗</div>
          <div class="how-title">Selecione seu veículo</div>
          <div class="how-text">Busque a marca e modelo do seu carro ou moto usando nossa integração com a tabela FIPE.</div>
        </div>
        <div class="how-card">
          <div class="how-num">2</div>
          <div class="how-icon">📝</div>
          <div class="how-title">Descreva o problema</div>
          <div class="how-text">Relate o que aconteceu com detalhes: defeito mecânico, atendimento ruim, problema recorrente.</div>
        </div>
        <div class="how-card">
          <div class="how-num">3</div>
          <div class="how-icon">📊</div>
          <div class="how-title">Ajuda quem vai comprar</div>
          <div class="how-text">Sua reclamação alimenta o ranking de confiabilidade e alerta futuros compradores.</div>
        </div>
        <div class="how-card">
          <div class="how-num">4</div>
          <div class="how-icon">✅</div>
          <div class="how-title">Acompanhe a resolução</div>
          <div class="how-text">Receba atualizações e marque sua reclamação como resolvida quando o problema for solucionado.</div>
        </div>
      </div>
    </div>
  </section>
</div>

<!-- ══ PAGE VEHICLE PROFILE ══ -->
<div id="page-vehicle" style="display:none;padding:32px 24px;max-width:1280px;margin:0 auto">
  <button class="back-btn" onclick="showPage('home')">← Voltar para o início</button>
  <div id="vehicle-profile-content"></div>
</div>

<!-- ══ PAGE ALL VEHICLES ══ -->
<div id="page-all-vehicles" style="display:none;padding:32px 24px;max-width:1280px;margin:0 auto">
  <button class="back-btn" onclick="showPage('home')">← Voltar para o início</button>
  <div class="section-header">
    <h2 class="section-title">Todos os Veículos <span class="accent">Avaliados</span></h2>
  </div>
  <div class="vehicles-grid" id="all-vehicles-grid"></div>
</div>

<!-- ══ FOOTER ══ -->
<footer>
  <div class="footer-inner">
    <a class="footer-logo" href="#">
      <img src="data:image/png;base64," alt="Doutor Oficina" style="height:88px;width:auto;">

    </a>
    <span class="footer-copy">© 2025 Doutor Oficina. Todos os direitos reservados.</span>
    <div class="footer-links">
      <a href="#">Privacidade</a>
      <a href="#">Termos</a>
      <a href="#">Contato</a>
    </div>
  </div>
</footer>

<!-- ══ AUTH MODAL ══ -->
<div class="auth-overlay" id="auth-modal">
  <div class="auth-box">
    <div class="auth-header">
      <div class="auth-logo-wrap" id="auth-logo-wrap"></div>
      <div class="auth-title" id="auth-modal-title">Entrar na sua conta</div>
      <div class="auth-subtitle">Para reclamar você precisa estar logado</div>
      <button class="auth-close" onclick="closeAuth()">✕</button>
    </div>
    <div class="auth-tabs" id="auth-tabs-header">
      <button class="auth-tab active" id="tab-login" onclick="switchAuth('login')">Entrar</button>
      <button class="auth-tab" id="tab-register" onclick="switchAuth('register')">Criar conta</button>
    </div>
    <div class="auth-body">
      <!-- Painel de Login -->
      <div class="auth-panel active" id="panel-login">
        <div class="auth-error" id="login-error">E-mail ou senha incorretos.</div>
        <div class="auth-group"><label class="auth-label">E-mail</label><input type="email" class="auth-input" id="login-email" placeholder="seu@email.com"/></div>
        <div class="auth-group"><label class="auth-label">Senha</label><input type="password" class="auth-input" id="login-pass" placeholder="••••••••" onkeydown="if(event.key==='Enter')doLogin()"/></div>
        <div style="text-align: right; margin-top: -10px; margin-bottom: 15px;">
          <a href="#" onclick="showForgotPanel()" style="font-size: 13px; color: var(--muted); text-decoration: none;">Esqueci minha senha</a>
        </div>
        <button class="auth-btn" onclick="doLogin()">Entrar →</button>

      </div>
      
      <!-- Painel de Cadastro -->
      <div class="auth-panel" id="panel-register">
        <div class="auth-error" id="register-error">E-mail já cadastrado.</div>
        <div class="auth-group"><label class="auth-label">Nome completo</label><input type="text" class="auth-input" id="reg-name" placeholder="Seu nome"/></div>
        <div class="auth-group"><label class="auth-label">E-mail</label><input type="email" class="auth-input" id="reg-email" placeholder="seu@email.com"/></div>
        <div class="auth-group"><label class="auth-label">Senha</label><input type="password" class="auth-input" id="reg-pass" placeholder="Mínimo 6 caracteres" onkeydown="if(event.key==='Enter')doRegister()"/></div>
        <button class="auth-btn" onclick="doRegister()">Criar conta →</button>
      </div>

      <!-- Painel de Esqueci a Senha -->
      <div class="auth-panel" id="panel-forgot">
        <div class="auth-error" id="forgot-error" style="display:none; color:var(--red); font-size:13px; margin-bottom:10px;"></div>
        <div class="auth-success" id="forgot-success" style="display:none; color:var(--green); font-size:13px; margin-bottom:10px;"></div>
        <div class="auth-group"><label class="auth-label">E-mail cadastrado</label><input type="email" class="auth-input" id="forgot-email" placeholder="seu@email.com"/></div>
        <button class="auth-btn" onclick="doForgot()">Enviar Link de Recuperação →</button>
        <div style="text-align: center; margin-top: 15px;">
          <a href="#" onclick="switchAuth('login')" style="font-size: 13px; color: var(--navy); text-decoration: none;">← Voltar para o Login</a>
        </div>
      </div>

      <!-- Painel de Redefinir Senha -->
      <div class="auth-panel" id="panel-reset">
        <div class="auth-error" id="reset-error" style="display:none; color:var(--red); font-size:13px; margin-bottom:10px;"></div>
        <div class="auth-group"><label class="auth-label">Nova Senha</label><input type="password" class="auth-input" id="reset-pass" placeholder="Mínimo 6 caracteres"/></div>
        <button class="auth-btn" onclick="doReset()">Alterar Senha →</button>
      </div>
    </div>
  </div>
</div>

<!-- ══ PAGE PERFIL ══ -->
<div id="page-profile" style="display:none">
  <div class="profile-page-wrap">
    <button class="back-btn" onclick="showPage('home')">← Voltar</button>
    <div class="user-hero">
      <div class="user-big-avatar" id="profile-avatar-big">U</div>
      <div class="user-info">
        <div class="user-real-name" id="profile-name-big">Usuário</div>
        <div class="user-email" id="profile-email-big">email@email.com</div>
        <div class="user-stats">
          <div class="ustat"><div class="ustat-n" id="profile-count">0</div><div class="ustat-l">Reclamações</div></div>
          <div class="ustat"><div class="ustat-n" id="profile-votes-total">0</div><div class="ustat-l">Votos recebidos</div></div>
          <div class="ustat"><div class="ustat-n" id="profile-resolved">0</div><div class="ustat-l">Resolvidas</div></div>
        </div>
      </div>
    </div>
    <div class="profile-card">
      <div class="pc-title"><span class="dot"></span>Minhas reclamações</div>
      <div class="my-complaints-list" id="my-complaints-list">
        <div style="color:var(--muted);font-size:14px;padding:12px 0">Você ainda não fez nenhuma reclamação.</div>
      </div>
    </div>
  </div>
</div>

<!-- ══ PAGE COMPARADOR ══ -->
<div id="page-compare" style="display:none">
  <div class="compare-wrap">
    <button class="back-btn" onclick="showPage('home')">← Voltar</button>
    <div class="section-title" style="margin-bottom:24px">⚖️ Comparar <span class="accent">veículos</span></div>
    <div class="compare-selectors">
      <div class="compare-sel-card">
        <div class="compare-sel-title">Veículo A</div>
        <select class="filter-select" style="width:100%;height:42px;margin-bottom:0" id="cmp-v1" onchange="renderComparison()">
          <option value="">Selecione…</option>
        </select>
      </div>
      <div class="compare-sel-card">
        <div class="compare-sel-title">Veículo B</div>
        <select class="filter-select" style="width:100%;height:42px;margin-bottom:0" id="cmp-v2" onchange="renderComparison()">
          <option value="">Selecione…</option>
        </select>
      </div>
    </div>
    <div id="compare-result"></div>
  </div>
</div>

<!-- ══ MODAL ══ -->
<div class="modal-overlay" id="modal">
  <div class="modal">
    <div class="modal-header">
      <h2 class="modal-title">Nova <span class="accent">reclamação</span></h2>
      <button class="modal-close" onclick="closeModal()">✕</button>
    </div>
    <div class="modal-body">
      <div class="step-indicator">
        <div class="step-dot done" id="dot0"></div>
        <div class="step-dot" id="dot1"></div>
        <div class="step-dot" id="dot2"></div>
      </div>

      <!-- STEP 1: Veículo -->
      <div class="modal-step active" id="step0">
        <div class="form-group">
          <label class="form-label">Tipo de veículo</label>
          <div class="vehicle-type-row" style="grid-template-columns:1fr 1fr 1fr">
            <button class="vtype-btn active" onclick="selectVehicleType(this,'carros')"><span class="vtype-icon">🚗</span>Carro</button>
            <button class="vtype-btn" onclick="selectVehicleType(this,'motos')"><span class="vtype-icon">🏍️</span>Moto</button>
            <button class="vtype-btn" onclick="selectVehicleType(this,'caminhoes')"><span class="vtype-icon">🚚</span>Caminhão</button>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label class="form-label">Marca</label>
            <select class="form-select" id="sel-brand" onchange="loadModels()">
              <option value="">Carregando...</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Modelo</label>
            <select class="form-select" id="sel-model" onchange="loadYears()" disabled>
              <option value="">Selecione a marca</option>
            </select>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label class="form-label">Ano</label>
            <select class="form-select" id="sel-year" onchange="loadFipePrice()" disabled>
              <option value="">Selecione o modelo</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Quilometragem aproximada</label>
            <input type="text" class="form-input" id="inp-km" placeholder="Ex: 45.000 km"/>
          </div>
        </div>
        <div class="fipe-info" id="fipe-info">
          <div>
            <div class="fipe-label">💰 Preço médio FIPE</div>
            <div class="fipe-price" id="fipe-price-val">—</div>
            <div class="fipe-label" id="fipe-ref" style="margin-top:2px">Referência: —</div>
          </div>
        </div>
        <div class="form-actions">
          <button class="btn-submit" onclick="goStep(1)">Próximo →</button>
        </div>
      </div>

      <!-- STEP 2: Problema -->
      <div class="modal-step" id="step1">
        <div class="form-group">
          <label class="form-label">Categoria do problema</label>
          <div class="category-grid">
            <button class="cat-btn" onclick="selectCat(this,'Motor/Mecânica')"><span class="cat-icon">⚙️</span>Motor</button>
            <button class="cat-btn" onclick="selectCat(this,'Elétrica')"><span class="cat-icon">⚡</span>Elétrica</button>
            <button class="cat-btn" onclick="selectCat(this,'Freios')"><span class="cat-icon">🛑</span>Freios</button>
            <button class="cat-btn" onclick="selectCat(this,'Suspensão')"><span class="cat-icon">🔧</span>Suspensão</button>
            <button class="cat-btn" onclick="selectCat(this,'Câmbio')"><span class="cat-icon">⚙️</span>Câmbio</button>
            <button class="cat-btn" onclick="selectCat(this,'Funilaria')"><span class="cat-icon">🎨</span>Funilaria</button>
            <button class="cat-btn" onclick="selectCat(this,'Ar-condicionado')"><span class="cat-icon">❄️</span>Ar-cond.</button>
            <button class="cat-btn" onclick="selectCat(this,'Concessionária')"><span class="cat-icon">🏢</span>Concession.</button>
            <button class="cat-btn" onclick="selectCat(this,'Outro')"><span class="cat-icon">📋</span>Outro</button>
          </div>
        </div>
        <div class="form-group" style="margin-top:4px">
          <label class="form-label">Título da reclamação</label>
          <input type="text" class="form-input" id="inp-title" placeholder="Ex: Motor superaquece em baixa velocidade"/>
        </div>
        <div class="form-group">
          <label class="form-label">Descreva o problema</label>
          <div id="inp-desc-container" style="height: 150px; background: var(--bg); border: 1.5px solid var(--border2); border-radius: 9px; margin-bottom: 8px;"></div>
<input type="hidden" id="inp-desc" name="descricao">
        </div>
        <div class="form-group">
          <label class="form-label">Sua avaliação geral do veículo</label>
          <div class="rating-row" id="star-rating">
            <button class="star-btn" onclick="setRating(1)">⭐</button>
            <button class="star-btn" onclick="setRating(2)">⭐</button>
            <button class="star-btn" onclick="setRating(3)">⭐</button>
            <button class="star-btn" onclick="setRating(4)">⭐</button>
            <button class="star-btn" onclick="setRating(5)">⭐</button>
          </div>
        </div>
        <div class="form-actions">
          <button class="btn-back" onclick="goStep(0)">← Voltar</button>
          <button class="btn-submit" onclick="goStep(2)">Próximo →</button>
        </div>
      </div>

      <!-- STEP 3: Seus dados -->
      <div class="modal-step" id="step2">
        <div class="form-row">
          <div class="form-group">
            <label class="form-label">Seu nome</label>
            <input type="text" class="form-input" id="inp-name" placeholder="Como prefere ser chamado"/>
          </div>
          <div class="form-group">
            <label class="form-label">E-mail</label>
            <input type="email" class="form-input" id="inp-email" placeholder="seu@email.com"/>
            <div class="form-hint">Usado apenas para acompanhar sua reclamação</div>
          </div>
        </div>
        <div class="form-group">
          <label class="form-label">Estado</label>
          <select class="form-select" id="sel-state">
            <option value="">Selecione…</option>
            <option>SP</option><option>RJ</option><option>MG</option><option>RS</option>
            <option>PR</option><option>SC</option><option>BA</option><option>GO</option>
            <option>PE</option><option>CE</option><option>AM</option><option>PA</option>
            <option>ES</option><option>MT</option><option>MS</option><option>RN</option>
            <option>PB</option><option>AL</option><option>SE</option><option>PI</option>
            <option>MA</option><option>RO</option><option>AC</option><option>TO</option>
            <option>AP</option><option>RR</option><option>DF</option>
          </select>
        </div>
        <div class="confirm-summary" id="confirm-summary"></div>
        <div class="form-actions">
          <button class="btn-back" onclick="goStep(1)">← Voltar</button>
          <button class="btn-submit" onclick="submitComplaint()">✅ Enviar reclamação</button>
        </div>
      </div>

      <!-- SUCCESS -->
      <div class="modal-step" id="step-success">
        <div class="success-box">
          <div class="success-icon">🎉</div>
          <div class="success-title">Reclamação enviada!</div>
          <div class="success-text">Obrigado por contribuir com a comunidade.<br>Sua reclamação já está visível e vai ajudar outros motoristas.</div>
          <button class="btn-submit" style="margin-top:24px;max-width:220px;display:block;margin-left:auto;margin-right:auto" onclick="closeModal()">Fechar</button>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- Quill.js JS -->
<script src="https://cdn.quilljs.com/1.3.6/quill.js"></script>
<script src="assets/js/app.js"></script>

</body>
</html>
